insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x3-c2$qa$, $qa$pemweb-x3$qa$, $qa$checkpoint$qa$, $qa$Urutkan specificity dari yang terendah ke tertinggi!$qa$, $qa$["ID < class < tipe < inline style", "Tipe < class/pseudo-class/atribut < ID < inline style", "Inline style < ID < class < tipe", "Class < tipe < ID < inline style"]$qa$::jsonb, 1, $qa$Selektor tipe paling lemah, lalu class, lalu ID, dan inline style paling kuat.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
