insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x3-b5$qa$, $qa$pemweb-x3$qa$, $qa$battle$qa$, $qa$Untuk memilih semua elemen yang memiliki class="tombol", selektor yang tepat adalah...$qa$, $qa$["#tombol", "tombol", ".tombol", "*tombol"]$qa$::jsonb, 2, $qa$Selektor class diawali titik; # adalah untuk ID dan nama polos untuk selektor tipe.$qa$, 5) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
